WITH p AS (SELECT r.DATASET_NAME,TRY_PARSE_JSON(d.PAYLOAD_JSON) AS p FROM VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_RUNS r JOIN VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_ROWS d ON r.RUN_ID=d.RUN_ID) SELECT DATASET_NAME,p:record_type::STRING AS RECORD_TYPE,COUNT(*) AS N_ROWS,COUNT_IF(p:available_at_utc IS NULL OR IS_NULL_VALUE(p:available_at_utc)) AS MISSING_AVAILABLE,MIN(p:available_at_utc::STRING) AS FIRST_AVAILABLE,MAX(p:available_at_utc::STRING) AS LAST_AVAILABLE,MIN(TO_JSON(OBJECT_KEYS(p:data))) AS DATA_KEYS,MIN(TO_JSON(OBJECT_KEYS(p:context))) AS CONTEXT_KEYS,ARRAY_UNIQUE_AGG(TO_JSON(p:quality_flags)) AS QUALITY_FLAGS FROM p GROUP BY 1,2 ORDER BY 1,2
